'use client'

/**
 * 系统 Logo 的纯 SVG 形状(流体「W」+ 右上角圆点)。
 *
 * 形状来源:由系统 logo 位图矢量化后提取的精确轮廓(W 主体 + 圆点),
 * 已归一化到 0–120 视图坐标系;颜色与渐变为本系统玻璃风强调蓝(左深右浅)。
 *
 * 设计要点:
 * - 几何只声明一次(<defs> 中的 path),fill 通过 <use> 复用,单一来源。
 * - 默认即为完整正确的静态 logo,不依赖任何外部 CSS。
 * - 主体与圆点分别带 `.logo-shape__art` / `.logo-shape__dot` class,
 *   供使用方叠加加载动效(如「液态浮动」:主体轻浮 + 圆点弹跳)。
 *
 * 每个实例必须传入唯一 `uid`,用于隔离 SVG 内部 id(gradient),同页多实例避免冲突。
 */

interface BrandLogoShapeProps {
  uid: string
  size?: number
  className?: string
  title?: string
}

