export function BrandLogoShape({ uid, size = 120, className, title }: BrandLogoShapeProps) {
  const gradId = `${uid}-grad`
  const dotGradId = `${uid}-grad-dot`
  const wId = `${uid}-w`
  const dotId = `${uid}-dot`

  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 120 120"
      xmlns="http://www.w3.org/2000/svg"
      role={title ? 'img' : 'presentation'}
      aria-hidden={title ? undefined : true}
    >
      {title ? <title>{title}</title> : null}

      <defs>
        <linearGradient id={gradId} x1="0.08" y1="0.15" x2="0.95" y2="0.95">
          <stop offset="0" stopColor="#1f63ff" />
          <stop offset="0.5" stopColor="#3f86ff" />
          <stop offset="1" stopColor="#b6d4ff" />
        </linearGradient>
        <linearGradient id={dotGradId} x1="0.1" y1="0.1" x2="0.9" y2="0.95">
          <stop offset="0" stopColor="#5a9bff" />
          <stop offset="1" stopColor="#3f86ff" />
        </linearGradient>

        {/* 几何唯一声明,供 fill 复用 */}
        <path id={wId} d={W_PATH} />
        <path id={dotId} d={DOT_PATH} />
      </defs>

      <g className="logo-shape__art">
        <use href={`#${wId}`} fill={`url(#${gradId})`} />
        <use href={`#${dotId}`} fill={`url(#${dotGradId})`} className="logo-shape__dot" />
      </g>
    </svg>
  )
}
